contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient balance");

        // Fund c with `amount` wei so that the withdrawAll call has a non-zero balance to move.
        c.sendMoney(address(this), amount); if (__ESBMC_reverted()) return;

        uint cBalanceBefore = address(c).balance;
        uint senderBalanceBefore = address(this).balance;

        require(cBalanceBefore == amount, "funding failed");

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint cBalanceAfter = address(c).balance;
        uint senderBalanceAfter = address(this).balance;

        assert(cBalanceAfter == 0 && senderBalanceAfter == senderBalanceBefore + cBalanceBefore);
    }

    receive() external payable {}
}

